action.code:
if (internal_key.size() < 8) {
  return false;
}
const char* ptr = internal_key.data() + internal_key.size() - 8;
uint64_t packed = DecodeFixed64(ptr);
*type = static_cast<uint8_t>(packed & 0xFF);
*sequence = packed >> 8;
if (*sequence > kMaxSequenceNumber) {
  return false;
}
*user_key = Slice(internal_key.data(), internal_key.size() - 8);
return true;

